#!/usr/bin/env python3
import sys
import argparse
from html.parser import HTMLParser
import html

class HTML2MarkdownParser(HTMLParser):
    def __init__(self, strong_delim='**', domain=None, enable_strike=False, enable_table=False):
        super().__init__()
        self.out = []
        self.stack = []
        self.strong_delim = strong_delim
        self.domain = domain
        self.enable_strike = enable_strike
        self.enable_table = enable_table
        self.list_stack = []  # ('ul' or 'ol', index)
        self.table_rows = None
        self.current_row = None
        self.in_pre = False
        self.skip_escape = False

