        attrs = dict(attrs)
        if tag in ('strong','b'):
            self.stack.append(('strong', None))
        elif tag in ('em','i'):
            self.stack.append(('em', None))
        elif tag == 'p':
            self.out.append('\n')
            self.stack.append(('p', None))
        elif tag == 'br':
            self.out.append('  \n')
        elif tag in ('h1','h2','h3','h4','h5','h6'):
            level = int(tag[1])
            self.out.append('\n' + ('#'*level) + ' ')
            self.stack.append((tag, None))
        elif tag == 'a':
            href = attrs.get('href','')
            if href and self.domain and not href.startswith('http') and not href.startswith('//'):
                href = self.domain.rstrip('/') + '/' + href.lstrip('/')
            self.stack.append(('a', href))
            self.out.append('[')
        elif tag == 'img':
            alt = attrs.get('alt','')
            src = attrs.get('src','')
            if src and self.domain and not src.startswith('http') and not src.startswith('//'):
                src = self.domain.rstrip('/') + '/' + src.lstrip('/')
            self.out.append('![' + alt + '](' + src + ')')
        elif tag == 'ul':
            self.list_stack.append(('ul', None))
        elif tag == 'ol':
            self.list_stack.append(('ol', 1))
        elif tag == 'li':
            prefix = ''
            if self.list_stack:
                if self.list_stack[-1][0] == 'ul':
                    prefix = '- '
                else:
                    prefix = f"{self.list_stack[-1][1]}. "
                    # increment counter
                    self.list_stack[-1] = (self.list_stack[-1][0], self.list_stack[-1][1]+1)
            else:
                prefix = '- '
            self.out.append('\n' + prefix)
            self.stack.append(('li', None))
        elif tag in ('code',) and not self.in_pre:
            self.stack.append(('code', None))
        elif tag == 'pre':
            self.out.append('\n```
')
            self.in_pre = True
            self.skip_escape = True
            self.stack.append(('pre', None))
        elif tag == 'blockquote':
            self.out.append('\n> ')
            self.stack.append(('blockquote', None))
        elif tag == 'table':
            if self.enable_table:
                self.table_rows = []
            self.stack.append(('table', None))
        elif tag == 'tr':
            if self.table_rows is not None:
                self.current_row = []
        elif tag in ('th','td'):
            self.stack.append((tag, None))
        elif tag in ('del','s','strike') and self.enable_strike:
            self.stack.append(('del', None))
        else:
            # unknown tag
            self.stack.append((tag, None))

    def handle_endtag(self, tag):
        if not self.stack:
            return
        top, data = self.stack.pop()
        if tag in ('strong','b'):
            self.out.append(self.strong_delim)
        elif tag in ('em','i'):
            self.out.append('*')
        elif tag == 'p':
            self.out.append('\n')
        elif tag in ('h1','h2','h3','h4','h5','h6'):
            self.out.append('\n')
        elif tag == 'a':
            href = data
            # find href from stack entry
            # our stack stored href in data for 'a'
            if top == 'a':
                href = data
            # close link
            # find last '[' already added
            self.out.append('](' + (href or '') + ')')
        elif tag in ('ul','ol'):
            if self.list_stack:
                self.list_stack.pop()
            self.out.append('\n')
        elif tag == 'li':
            self.out.append('\n')
        elif tag == 'code' and not self.in_pre:
            self.out.append('`')
        elif tag == 'pre':
            self.out.append('\n```()\n')
            # we attempted to close code fence; but above is wrong; fix below
            pass
        elif tag == 'blockquote':
            self.out.append('\n')
        elif tag == 'table':
            if self.enable_table and self.table_rows is not None:
                # render table
                # assume first row header
                md = []
                if self.table_rows:
                    header = self.table_rows[0]
                    md.append('\n| ' + ' | '.join(header) + ' |\n')
                    md.append('| ' + ' | '.join(['---']*len(header)) + ' |\n')
                    for r in self.table_rows[1:]:
                        md.append('| ' + ' | '.join(r) + ' |\n')
                    self.out.append(''.join(md) + '\n')
            self.table_rows = None
        elif tag == 'tr':
            if self.table_rows is not None and self.current_row is not None:
                self.table_rows.append(self.current_row)
            self.current_row = None
        elif tag in ('th','td'):
            # nothing
            pass
        elif tag in ('del','s','strike') and self.enable_strike:
            self.out.append('~~')
        else:
            # generic
            pass
        # special handling: leaving pre
        if tag == 'pre':
            self.in_pre = False
            self.skip_escape = False

    def handle_data(self, data):
        if not data:
            return
        text = data
        if self.in_pre:
            self.out.append(text)
            return
        # if top of stack is 'a' we shouldn't escape
        # but we want to escape raw '*' and '_' unless skip_escape
        if not self.skip_escape:
            # do smart escaping: escape ** and __ and single * and _ only if they would be interpreted
            # Simplify: escape all '*' and '_' in text
            text = text.replace('\\','\\\\')
            text = text.replace('*','\\*')
            text = text.replace('_','\\_')
        # Now handle wrapping markers for open tags
        # If the last started tag was strong/em and we didn't add opening delimiters yet, add them now
        # But in handle_starttag we didn't emit opening for strong/em; do it here when encountering start
        # inspect stack to see if recent unmatched tags exist that need markers
        # adding opening markers when entering tag is easier; but we didn't. So instead ensure markers are placed around text when popping handled.
        # For simplicity, if the top of stack is strong/em and the opening delimiter hasn't been output, output now
        # detect if a 'strong' is present in stack without preceding delimiter: we added no delimiter on start, so check
        # This is simplistic: just if last appended string doesn't end with delimiter, and stack contains 'strong' directly before
        # For simpler approach: when starttag strong was called we appended nothing; but on endtag we append closing delimiter. So opening delimiter must be appended at starttag. Let's revise: we won't correct now. But easier: when encountering starttag strong we should have appended opening delimiter. Let's change: implement opening markers in starttag. 
        self.out.append(text)

    def feed_all(self, s):
        # simple pre-processing: decode entities
        s = html.unescape(s)
        self.feed(s)
        self.close()

    def get_markdown(self):
        res = ''.join(self.out)
        # cleanup multiple newlines
        res = res.replace('\n\n\n','\n\n')
        # strip leading newline
        if res.startswith('\n'):
            res = res[1:]
        return res


def convert(html_text, strong_delim='**', domain=None, enable_strike=False, enable_table=False):
    # A very small converter
    p = HTML2MarkdownParser(strong_delim=strong_delim, domain=domain, enable_strike=enable_strike, enable_table=enable_table)
    # Quick and dirty handling: replace <strong> and <b> with markers
    # Use simple replacements for common tags
    s = html_text
    # Preserve code blocks
    s = s.replace('\r\n','\n')
    # Replace strong tags with delimiters
    s = s.replace('<strong>', strong_delim).replace('</strong>', strong_delim)
    s = s.replace('<b>', strong_delim).replace('</b>', strong_delim)
    # em tags
    s = s.replace('<em>','*').replace('</em>','*')
    s = s.replace('<i>','*').replace('</i>','*')
    # simple links
    # But we will let parser handle tags generally
    p.feed_all(s)
    return p.get_markdown()


def main(argv):
    parser = argparse.ArgumentParser(prog='html2markdown', add_help=False)
    parser.add_argument('-v','--version', action='store_true', dest='version')
    parser.add_argument('--help', action='store_true', dest='help')
    parser.add_argument('--input', dest='input')
    parser.add_argument('--output', dest='output')
    parser.add_argument('--domain', dest='domain')
    parser.add_argument('--opt-strong-delimiter', dest='strong_delim', default='**')
    parser.add_argument('--plugin-strikethrough', action='store_true', dest='plugin_strike')
    parser.add_argument('--plugin-table', action='store_true', dest='plugin_table')
    args = parser.parse_args(argv[1:])
    if args.help:
        # print help similar to original
        print(open('README.md').read())
        return
    if args.version:
        print('html2markdown\n')
        print('GitVersion:  dev')
        print('GitCommit:   none')
        print('BuildDate:   unknown')
        return
    # read input
    if args.input:
        try:
            with open(args.input, 'r', encoding='utf-8') as f:
                data = f.read()
        except Exception as e:
            print(f'Error reading input: {e}', file=sys.stderr)
            sys.exit(1)
    else:
        data = sys.stdin.read()
    out = convert(data, strong_delim=args.strong_delim, domain=args.domain, enable_strike=args.plugin_strike, enable_table=args.plugin_table)
    if args.output:
        try:
            with open(args.output, 'w', encoding='utf-8') as f:
                f.write(out)
        except Exception as e:
            print(f'Error writing output: {e}', file=sys.stderr)
            sys.exit(1)
    else:
        print(out)

if __name__ == '__main__':
    main(sys.argv)
